import{_ as n,o as t,c as a,a5 as i}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"Se connecter à son compte Cloud","description":"","frontmatter":{"title":"Se connecter à son compte Cloud","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"64776a7488c087fd24c2ab47fe38337704bd2d5f90df391eebae64bd310b8048","order":10},"headers":[],"relativePath":"fr/user/cloud/account.md","filePath":"fr/user/cloud/account.md","lastUpdated":1794611623000}'),o={name:"fr/user/cloud/account.md"};function s(r,e,c,l,u,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Se connecter à son compte Cloud <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;Se connecter à son compte Cloud {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Connecter l’application de bureau à son service Cloud configuré pour les opérations de catalogue et de collaboration liées au compte. Il faut un accès réseau, un navigateur système et un coffre d’identifiants du système d’exploitation fonctionnel. L’édition locale reste utile sans Cloud ; une session Cloud n’authentifie pas votre connexion TikTok LIVE.</p><h2 id="sign-in-and-verify-identity" tabindex="-1">Se connecter et vérifier l’identité <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;Se connecter et vérifier l’identité {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li>Ouvrez <strong>Settings → Account</strong>. Lisez l’état actuel avant de démarrer une nouvelle connexion.</li><li>Sélectionnez <strong>Sign in</strong>. Le bureau démarre un récepteur de rappel local et ouvre la page de connexion configurée dans le navigateur système.</li><li>Terminez le parcours de connexion du service et revenez à TikTools. Si le navigateur ne s’est pas ouvert, utilisez l’URL de connexion affichée par l’application pour cette tentative. Traitez cette URL comme privée et ne la publiez pas.</li><li>Attendez que l’état du compte indique une connexion établie. Confirmez le nom ou l’adresse électronique affichés avant d’ouvrir un catalogue privé ou une équipe.</li><li>Ouvrez la section des diagnostics de Account si l’état signale une erreur. Utilisez <strong>Cancel</strong> pour abandonner une tentative inachevée plutôt que de laisser plusieurs tentatives actives.</li><li>Après utilisation d’un ordinateur partagé, sélectionnez <strong>Sign out</strong> et vérifiez le changement d’état du compte.</li></ol><p>L’hôte natif gère le jeton de session. Il stocke les identifiants via le coffre du système d’exploitation et ne conserve dans l’interface qu’un état non secret. Aucun repli vers un fichier en clair n’existe lorsque le stockage sécurisé est indisponible. Un dossier de données copié ne constitue pas une session connectée portable.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>La connexion native, la restauration et la déconnexion sont disponibles dans les hôtes compilés avec l’authentification Cloud. Un compte configuré peut être restauré au redémarrage et revalidé auprès du service. Un hôte non configuré ou non pris en charge ne se corrige pas en saisissant un autre cookie TikTok.</p><p>La disponibilité de la connexion au service et la validation réelle du fournisseur/de la plateforme dépendent du service déployé et de votre machine. Une validation locale ne prouve pas que tous les parcours de connexion en production fonctionnent.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Pour une tentative annulée ou expirée, lancez une nouvelle connexion après avoir fermé l’ancienne. En cas d’erreur réseau ou de service, conservez le code de diagnostic et réessayez après rétablissement. Pour une erreur de coffre d’identifiants, rétablissez le stockage sécurisé du système ; ne collez pas de jeton porteur dans les paramètres ou un message d’assistance. Consultez <a href="./changes.html">Changes</a> pour la synchronisation explicite et la <a href="./collaboration.html">collaboration</a> pour les autorisations d’accès distinctes.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>La déconnexion supprime les identifiants locaux et le contexte avant une tentative de révocation serveur au mieux. L’UI déconnectée confirme la suppression locale, pas la révocation distante en cas de panne réseau. Utilisez l’administration des sessions du service si elle existe. Exportez Diagnostics avant déconnexion/changement d’un compte connu : cet historique UI est effacé. Cookies TikTok et sessions d’hôte distant sont des identités distinctes.</p>',13)])])}const v=n(o,[["render",s]]);export{f as __pageData,v as default};
